from typing import Any, Iterable


def format_results_table(rows: Iterable[dict[str, Any]], columns: list[str] | None = None, max_cell_chars: int = 120) -> str:
    """Format account search results as a Markdown table.

    Args:
        rows: Iterable of dictionaries representing matched accounts.
        columns: Optional ordered list of columns to include. If omitted, columns are inferred.
        max_cell_chars: Maximum displayed characters per cell.

    Returns:
        A Markdown table string, or a short message if there are no rows.
    """
    data = list(rows)
    if not data:
        return "No matching accounts found."

    if columns is None:
        preferred = [
            "account_id",
            "account_name",
            "name",
            "source_dataset",
            "matched_fields",
            "evidence",
            "confidence",
        ]
        discovered: list[str] = []
        for row in data:
            for key in row.keys():
                if key not in discovered:
                    discovered.append(key)
        columns = [c for c in preferred if c in discovered] + [c for c in discovered if c not in preferred]

    def clean(value: Any) -> str:
        if value is None:
            text = ""
        elif isinstance(value, (list, tuple, set)):
            text = ", ".join(str(item) for item in value)
        elif isinstance(value, dict):
            text = "; ".join(f"{k}: {v}" for k, v in value.items())
        else:
            text = str(value)
        text = text.replace("\n", " ").replace("|", "\\|").strip()
        if len(text) > max_cell_chars:
            text = text[: max_cell_chars - 1].rstrip() + "…"
        return text

    table = []
    table.append("| " + " | ".join(columns) + " |")
    table.append("| " + " | ".join("---" for _ in columns) + " |")
    for row in data:
        table.append("| " + " | ".join(clean(row.get(col)) for col in columns) + " |")
    return "\n".join(table)

from __future__ import annotations

from typing import Any, Iterable, Mapping
import pandas as pd


def format_results_table(rows: Any, max_rows: int = 50) -> str:
    """Format account-search results as a Markdown table.

    Accepts a pandas DataFrame, a list of dicts, a single dict, or any iterable
    of mappings. Returns a compact Markdown table suitable for the final answer.
    """
    if rows is None:
        return "No matching accounts found."

    if isinstance(rows, pd.DataFrame):
        df = rows.copy()
    elif isinstance(rows, Mapping):
        df = pd.DataFrame([dict(rows)])
    else:
        try:
            materialized = list(rows)
        except TypeError:
            materialized = [rows]
        if not materialized:
            return "No matching accounts found."
        df = pd.DataFrame(materialized)

    if df.empty:
        return "No matching accounts found."

    df = df.head(max_rows).fillna("")
    return df.to_markdown(index=False)

from typing import Iterable, Mapping, Any


def format_results_table(rows: Iterable[Mapping[str, Any]], columns: list[str] | None = None) -> str:
    """Return a compact Markdown table for run results.

    Args:
        rows: Iterable of dictionaries containing result fields.
        columns: Optional ordered list of columns to include. If omitted,
            columns are inferred from the first row.
    """
    rows = list(rows)
    if not rows:
        return "No structured results to display."

    if columns is None:
        columns = list(rows[0].keys())

    def clean(value: Any) -> str:
        text = "" if value is None else str(value)
        return text.replace("|", "\\|").replace("\n", " ").strip()

    table = []
    table.append("| " + " | ".join(columns) + " |")
    table.append("| " + " | ".join(["---"] * len(columns)) + " |")
    for row in rows:
        table.append("| " + " | ".join(clean(row.get(col, "")) for col in columns) + " |")
    return "\n".join(table)

from typing import Any, Iterable, Mapping


def format_results_table(rows: Iterable[Mapping[str, Any]]) -> str:
    """Format run result dictionaries as a compact Markdown table."""
    rows = list(rows)
    if not rows:
        return "No tabular results available."

    headers = []
    for row in rows:
        for key in row.keys():
            if key not in headers:
                headers.append(key)

    def cell(value: Any) -> str:
        if value is None:
            return ""
        text = str(value)
        return text.replace("|", "\\|").replace("\n", " ")

    table = []
    table.append("| " + " | ".join(headers) + " |")
    table.append("| " + " | ".join("---" for _ in headers) + " |")
    for row in rows:
        table.append("| " + " | ".join(cell(row.get(header)) for header in headers) + " |")
    return "\n".join(table)

from __future__ import annotations

from typing import Any, Iterable, Mapping


def format_results_table(rows: Iterable[Mapping[str, Any]]) -> str:
    """Format run results/metrics as a GitHub-flavored Markdown table.

    Expected input: an iterable of dictionaries, for example:
    [{"dataset": "new_data", "metric": "auc", "score": 0.91}]
    """
    rows = list(rows)
    if not rows:
        return "| status |\n|---|\n| no results |"

    columns: list[str] = []
    for row in rows:
        for key in row.keys():
            if key not in columns:
                columns.append(str(key))

    def cell(value: Any) -> str:
        if value is None:
            text = ""
        elif isinstance(value, float):
            text = f"{value:.6g}"
        else:
            text = str(value)
        return text.replace("|", "\\|").replace("\n", " ")

    header = "| " + " | ".join(columns) + " |"
    separator = "| " + " | ".join("---" for _ in columns) + " |"
    body = ["| " + " | ".join(cell(row.get(col, "")) for col in columns) + " |" for row in rows]
    return "\n".join([header, separator, *body])
